import java.util.*;

class Solution {
    public int[] rangeXor(int[] arr, int[][] queries) {
        int n = arr.length;
        int[] p = new int[n + 1];            // p[i] = XOR of arr[0..i-1]
        for (int i = 0; i < n; i++) p[i + 1] = p[i] ^ arr[i];
        int[] ans = new int[queries.length];
        for (int k = 0; k < queries.length; k++) {
            int l = queries[k][0], r = queries[k][1];
            ans[k] = p[r + 1] ^ p[l];        // common prefix before l cancels
        }
        return ans;
    }
}

